package com.example.examplemod.cargo.center;

import net.minecraft.nbt.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** All cash, debt, frozen trip reserves and receipts live in EconomyManager's one financial save. */
public final class RailTollBook {
    public record Road(UUID id,OwnerRef owner,String name,long rate,long revision,boolean active,List<RailGeometry.Span> spans){
        public Road {spans=List.copyOf(spans);if(id==null||owner==null||name==null||name.isBlank()||rate<0||rate>1_000_000_000L||revision<1||spans.isEmpty())throw new IllegalArgumentException("rail_road_invalid");}
    }
    public record Debt(UUID id,OwnerRef debtor,OwnerRef creditor,UUID road,long assessed,long paid){public long remaining(){return assessed-paid;}}
    public record TechnicalDebt(UUID id,UUID train,String name,OwnerRef creditor,UUID road,long assessed,OwnerRef resolved){}
    public record Charge(UUID road,OwnerRef creditor,long revision,long rate,RailGeometry.Span span){}
    private final CargoCommerceBook.Accounts accounts;
    private final Map<UUID,Road> roads=new LinkedHashMap<>();
    private final Map<UUID,Debt> debts=new LinkedHashMap<>();
    private final Map<UUID,TechnicalDebt> technical=new LinkedHashMap<>();
    private final Map<String,CompoundTag> technicalFractions=new HashMap<>();
    private final Map<UUID,CompoundTag> statistics=new HashMap<>();
    private final Map<UUID,Long> meterSequences=new HashMap<>();
    private static final UUID METER_NAMESPACE=UUID.fromString("83616588-9a64-4668-86d6-e85898ad335c");
    private final Map<String,Long> fractions=new HashMap<>();
    private final Map<UUID,CompoundTag> trips=new LinkedHashMap<>();
    private final Set<UUID> receipts=new HashSet<>();
    private final Map<String,CompoundTag> passages=new HashMap<>();
    private final Set<UUID> legacyOrders=new HashSet<>();
    private boolean legacyCaptured;
    public RailTollBook(CargoCommerceBook.Accounts accounts){this.accounts=Objects.requireNonNull(accounts);}
    public List<Road> roads(){return List.copyOf(roads.values());}
    public List<Debt> debts(){return List.copyOf(debts.values());}
    public List<TechnicalDebt> technicalDebts(){return List.copyOf(technical.values());}
    public boolean metered(UUID stream,long sequence){return sequence<=meterSequences.getOrDefault(stream,0L);}
    /** Physical observations use a stream high-water mark, not an ever-growing UUID per physics tick. */
    public void completeMeter(UUID stream,long sequence,UUID receipt){meterSequences.merge(stream,sequence,Math::max);receipts.remove(receipt);accounts.dirty();}
    public void meterTravel(UUID stream,long sequence,OwnerRef debtor,List<Charge> charges){if(metered(stream,sequence))return;UUID receipt=component(stream,Long.toString(sequence));travel(receipt,debtor,charges);record Group(UUID road,OwnerRef creditor){}var groups=new HashSet<Group>();for(var c:charges)if(!debtor.equals(c.creditor()))groups.add(new Group(c.road(),c.creditor()));
        for(var group:groups){UUID raw=component(receipt,group.toString());var assessed=debts.remove(raw);if(assessed!=null){UUID bucket=component(METER_NAMESPACE,debtor+"/"+group);var old=debts.get(bucket);debts.put(bucket,new Debt(bucket,debtor,group.creditor(),group.road(),Math.addExact(old==null?0:old.assessed(),assessed.assessed()),Math.addExact(old==null?0:old.paid(),assessed.paid())));}receipts.remove(component(receipt,"initial/"+group));}completeMeter(stream,sequence,receipt);
    }
    public void meterUnowned(UUID stream,long sequence,UUID train,String name,List<Charge> charges){if(metered(stream,sequence))return;UUID receipt=component(stream,Long.toString(sequence));travelUnowned(receipt,train,name,charges);record Group(UUID road,OwnerRef creditor){}var groups=new HashSet<Group>();for(var c:charges)groups.add(new Group(c.road(),c.creditor()));for(var group:groups){UUID raw=component(receipt,group.toString());var assessed=technical.remove(raw);if(assessed!=null){var meta=technicalFractions.get("TRAIN/"+train+"/"+group.creditor()+"/"+group.road());UUID bucket=component(meta.getUUID("Epoch"),group.toString());var old=technical.get(bucket);technical.put(bucket,new TechnicalDebt(bucket,train,name,group.creditor(),group.road(),Math.addExact(old==null?0:old.assessed(),assessed.assessed()),null));}}completeMeter(stream,sequence,receipt);}
    public CompoundTag statistics(UUID road){var t=statistics.getOrDefault(road,new CompoundTag()).copy();long outstanding=0;for(var d:debts.values())if(d.road().equals(road))outstanding=Math.addExact(outstanding,d.remaining());for(var d:technical.values())if(d.road().equals(road)&&d.resolved()==null)outstanding=Math.addExact(outstanding,d.assessed());t.putLong("Outstanding",outstanding);return t;}
    private void distance(UUID road,double amount){var t=statistics.computeIfAbsent(road,k->new CompoundTag());t.putDouble("Distance",t.getDouble("Distance")+amount);}
    private void paid(UUID road,long amount){var t=statistics.computeIfAbsent(road,k->new CompoundTag());t.putLong("Paid",Math.addExact(t.getLong("Paid"),amount));}
    public Optional<Road> road(UUID id){return Optional.ofNullable(roads.get(id));}
    public long totalDebt(OwnerRef owner){long total=0;for(var d:debts.values())if(d.debtor().equals(owner))total=Math.addExact(total,d.remaining());return total;}
    public boolean hasOutstanding(OwnerRef owner){return roads.values().stream().anyMatch(r->r.active()&&r.owner().equals(owner))||debts.values().stream().anyMatch(d->d.remaining()>0&&(d.debtor().equals(owner)||d.creditor().equals(owner)))||technical.values().stream().anyMatch(d->d.resolved()==null&&d.creditor().equals(owner))||technicalFractions.values().stream().anyMatch(t->OwnerRef.load(t.getCompound("Creditor")).equals(owner))||trips.values().stream().anyMatch(t->!t.getBoolean("Closed")&&references(t,owner));}
    private static boolean references(CompoundTag trip,OwnerRef owner){if(OwnerRef.load(trip.getCompound("Payer")).equals(owner))return true;var plan=trip.getCompound("Plan");if(plan.contains("Carrier")&&OwnerRef.load(plan.getCompound("Carrier")).equals(owner))return true;var phases=plan.getCompound("Phases");for(String phase:phases.getAllKeys())for(var raw:phases.getCompound(phase).getList("Charges",10))if(OwnerRef.load(((CompoundTag)raw).getCompound("Creditor")).equals(owner))return true;return false;}
    public void captureLegacy(Collection<CargoCommerceBook.Order> orders){if(legacyCaptured)return;for(var o:orders)if(o.state()!=CargoCommerceBook.State.REFUNDED&&o.state()!=CargoCommerceBook.State.CANCELLED)legacyOrders.add(o.id());legacyCaptured=true;accounts.dirty();}
    public boolean legacyCaptured(){return legacyCaptured;}
    public Set<UUID> legacyOrders(){return Set.copyOf(legacyOrders);}
    public void retireLegacy(UUID order){if(legacyOrders.remove(order))accounts.dirty();}
    public boolean legacy(UUID order){return legacyOrders.contains(order);}
    /** Persist the recipient and rate when an ordinary train enters a section; subsequent edits do not reprice that passage. */
    public List<Charge> passage(UUID train,List<Charge> current){String prefix=train+"/";var live=new HashSet<String>();var result=new ArrayList<Charge>();boolean changed=false;for(var c:current){String key=prefix+c.road();live.add(key);var entry=passages.get(key);if(entry==null){entry=new CompoundTag();entry.put("Creditor",c.creditor().save());entry.putLong("Rate",c.rate());entry.putLong("Revision",c.revision());passages.put(key,entry);changed=true;}result.add(new Charge(c.road(),OwnerRef.load(entry.getCompound("Creditor")),entry.getLong("Revision"),entry.getLong("Rate"),c.span()));}var iterator=passages.keySet().iterator();while(iterator.hasNext()){String key=iterator.next();if(key.startsWith(prefix)&&!live.contains(key)){iterator.remove();changed=true;}}if(changed)accounts.dirty();return List.copyOf(result);}
    public Road register(UUID id,OwnerRef owner,String name,long rate,List<RailGeometry.Span> spans){
        if(roads.containsKey(id))throw new IllegalArgumentException("rail_road_duplicate");
        spans=normalize(spans);
        for(var span:spans)for(var road:roads.values())if(road.active())for(var occupied:road.spans())if(span.overlap(occupied)>0.001)throw new IllegalArgumentException("rail_road_overlap: "+road.name());
        var road=new Road(id,owner,name,rate,1,true,spans);roads.put(id,road);accounts.dirty();return road;
    }
    private static List<RailGeometry.Span> normalize(List<RailGeometry.Span> input){var sorted=new ArrayList<>(input);sorted.sort(Comparator.comparing(RailGeometry.Span::shape).thenComparingDouble(RailGeometry.Span::from));var result=new ArrayList<RailGeometry.Span>();for(var span:sorted){if(span.to()-span.from()<1e-8)continue;if(!result.isEmpty()){var last=result.getLast();if(last.shape().equals(span.shape())&&last.to()>=span.from()-.00001){result.set(result.size()-1,new RailGeometry.Span(last.shape(),last.from(),Math.max(last.to(),span.to())));continue;}}result.add(span);}return List.copyOf(result);}
    public void revise(UUID id,long rate,boolean active){var old=roads.get(id);if(old==null)throw new IllegalArgumentException("rail_road_missing");if(!active&&roadInUse(id))throw new IllegalArgumentException("rail_road_in_use");roads.put(id,new Road(id,old.owner(),old.name(),rate,Math.addExact(old.revision(),1),active,old.spans()));accounts.dirty();}
    public boolean roadInUse(UUID id){if(passages.keySet().stream().anyMatch(key->key.endsWith("/"+id)))return true;for(var trip:trips.values())if(!trip.getBoolean("Closed")){var phases=trip.getCompound("Plan").getCompound("Phases");for(String phase:phases.getAllKeys())for(var raw:phases.getCompound(phase).getList("Charges",10))if(((CompoundTag)raw).getUUID("Road").equals(id))return true;}return false;}
    public List<Charge> charges(RailGeometry.Span travelled){var result=new ArrayList<Charge>();for(var road:roads.values())if(road.active())for(var span:road.spans()){
        double overlap=span.overlap(travelled);if(overlap>1e-8)result.add(new Charge(road.id(),road.owner(),road.revision(),road.rate(),new RailGeometry.Span(span.shape(),Math.max(span.from(),travelled.from()),Math.min(span.to(),travelled.to()))));}return List.copyOf(result);}
    public static long units(double metres,long rate){if(!Double.isFinite(metres)||metres<0||rate<0)throw new IllegalArgumentException("rail_distance_invalid");return BigDecimal.valueOf(metres).multiply(BigDecimal.valueOf(rate)).multiply(BigDecimal.valueOf(1000)).setScale(0,RoundingMode.HALF_UP).longValueExact();}
    public static long ceiling(long microCR){return Math.addExact(microCR/1_000_000,microCR%1_000_000==0?0:1);}
    public long estimate(List<RailGeometry.Span> spans,OwnerRef payer){var groups=new HashMap<String,Long>();for(var span:spans)for(var c:charges(span))if(!payer.equals(c.creditor())){String key=payer+"/"+c.creditor()+"/"+c.road();groups.merge(key,units(c.span().to()-c.span().from(),c.rate()),Math::addExact);}long total=0;for(var e:groups.entrySet())total=Math.addExact(total,ceiling(Math.addExact(e.getValue(),fractions.getOrDefault(e.getKey(),0L))));return total;}
    public void reserveTrip(UUID order,OwnerRef payer,long amount,CompoundTag plan){
        var existing=trips.get(order);if(existing!=null){if(!OwnerRef.load(existing.getCompound("Payer")).equals(payer)||existing.getLong("Reserved")!=amount||!existing.getCompound("Plan").equals(plan))throw new IllegalArgumentException("rail_trip_identity_conflict");return;}
        if(amount<0||amount>accounts.maximum()||!accounts.debit(payer,amount))throw new IllegalArgumentException("rail_trip_insufficient_cr");
        var t=new CompoundTag();t.put("Payer",payer.save());t.putLong("Reserved",amount);t.putLong("Remaining",amount);t.put("Plan",plan.copy());t.putString("Phase","APPROACH");t.putInt("Cursor",0);trips.put(order,t);accounts.dirty();
    }
    public Optional<CompoundTag> trip(UUID id){var t=trips.get(id);return t==null?Optional.empty():Optional.of(t.copy());}
    public Optional<RailGeometry.Span> consumed(UUID order,String phase,int segment){var t=trips.get(order);String key=phase+"/"+segment;return t==null||!t.getCompound("Consumed").contains(key)?Optional.empty():Optional.of(RailGeometry.Span.load(t.getCompound("Consumed").getCompound(key)));}
    private static RailGeometry.Span unseen(RailGeometry.Span actual,RailGeometry.Span previous){if(previous==null)return actual;if(!previous.shape().equals(actual.shape()))return null;if(previous.overlap(actual)<=.00001)return Math.max(previous.from(),actual.from())-Math.min(previous.to(),actual.to())<=.00001?actual:null;if(actual.from()>=previous.from()-.00001&&actual.to()<=previous.to()+.00001)return null;if(actual.from()<previous.from()-.00001&&actual.to()>previous.to()+.00001)return null;return actual.to()>previous.to()?new RailGeometry.Span(actual.shape(),previous.to(),actual.to()):new RailGeometry.Span(actual.shape(),actual.from(),previous.from());}
    public void phase(UUID order,String phase){var t=trips.get(order);if(t!=null&&!phase.equals(t.getString("Phase"))){t.putString("Phase",phase);t.putInt("Cursor",0);accounts.dirty();}}
    /** Ordered coverage is consumed once. Repeated loops cannot spend a buyer's reserved funds. */
    public boolean tripTravel(UUID receipt,UUID order,String phase,int segment,RailGeometry.Span actual,List<Charge> frozen){
        var t=trips.get(order);if(t==null||t.getBoolean("Closed")||!phase.equals(t.getString("Phase"))||segment<t.getInt("Cursor"))return false;
        if(receipts.contains(receipt))return true;
        var consumed=t.getCompound("Consumed");String progressKey=phase+"/"+segment;var previous=consumed.contains(progressKey)?RailGeometry.Span.load(consumed.getCompound(progressKey)):null;
        actual=unseen(actual,previous);if(actual==null)return false;
        OwnerRef payer=OwnerRef.load(t.getCompound("Payer"));long micro=0;var amounts=new LinkedHashMap<OwnerRef,Long>();var pending=new HashMap<String,Long>();var paidRoads=new HashMap<UUID,Long>();
        for(var c:frozen){double distance=actual.overlap(c.span());if(distance>0&&!payer.equals(c.creditor())){
            String key=payer+"/"+c.creditor()+"/"+c.road();long sum=Math.addExact(pending.getOrDefault(key,fractions.getOrDefault(key,0L)),units(distance,c.rate()));long amount=sum/1_000_000;pending.put(key,sum%1_000_000);micro=Math.addExact(micro,amount);amounts.merge(c.creditor(),amount,Math::addExact);paidRoads.merge(c.road(),amount,Math::addExact);
        }}
        if(micro>t.getLong("Remaining"))return false;
        fractions.putAll(pending);
        var queue=t.getList("Payables",10);for(var e:paidRoads.entrySet())if(e.getValue()>0){var charge=frozen.stream().filter(c->c.road().equals(e.getKey())).findFirst().orElseThrow();CompoundTag payable=null;for(var raw:queue){var candidate=(CompoundTag)raw;if(candidate.getUUID("Road").equals(e.getKey())&&OwnerRef.load(candidate.getCompound("Creditor")).equals(charge.creditor())){payable=candidate;break;}}if(payable==null){payable=new CompoundTag();payable.putUUID("Id",component(receipt,e.getKey().toString()));payable.putUUID("Road",e.getKey());payable.put("Creditor",charge.creditor().save());queue.add(payable);}payable.putLong("Amount",Math.addExact(payable.getLong("Amount"),e.getValue()));}t.put("Payables",queue);
        for(var c:frozen){double length=actual.overlap(c.span());if(length>0)distance(c.road(),length);}
        if(previous!=null)actual=new RailGeometry.Span(actual.shape(),Math.min(previous.from(),actual.from()),Math.max(previous.to(),actual.to()));consumed.put(progressKey,actual.save());t.put("Consumed",consumed);
        t.putLong("Remaining",t.getLong("Remaining")-micro);t.putInt("Cursor",segment);receipts.add(receipt);flushPayables(t);accounts.dirty();return true;
    }
    private boolean flushPayables(CompoundTag trip){var queue=trip.getList("Payables",10);if(queue.isEmpty())return true;var amounts=new HashMap<OwnerRef,Long>();for(var raw:queue){var p=(CompoundTag)raw;amounts.merge(OwnerRef.load(p.getCompound("Creditor")),p.getLong("Amount"),Math::addExact);}if(!accounts.canReceivePayments(amounts,Map.of()))return false;for(var raw:queue){var p=(CompoundTag)raw;accounts.revenue(p.getUUID("Id"),OwnerRef.load(p.getCompound("Creditor")),p.getLong("Amount"));paid(p.getUUID("Road"),p.getLong("Amount"));}trip.put("Payables",new ListTag());accounts.dirty();return true;}
    public Optional<RailRoutes.Path> headPath(UUID order,String phase){var trip=trips.get(order);if(trip==null||!trip.getCompound("HeadPaths").contains(phase))return Optional.empty();return Optional.of(RailRoutes.Path.load(trip.getCompound("HeadPaths").getCompound(phase)));}
    /** Anchor the actual departure wheel coordinate on the same approved first directed edge. */
    public void anchorHead(UUID order,String phase,RailRoutes.Path actual){var trip=trips.get(order);if(trip==null||trip.getBoolean("Closed"))throw new IllegalArgumentException("rail_trip_missing");var paths=trip.getCompound("HeadPaths");if(paths.contains(phase))return;var expected=RailRoutes.Path.load(trip.getCompound("Plan").getCompound("Phases").getCompound(phase).getCompound("Path"));if(!expected.destination().equals(actual.destination())||expected.backwards()!=actual.backwards()||expected.segments().size()!=actual.segments().size())throw new IllegalArgumentException("fleet_phase_start_changed");for(int i=0;i<expected.segments().size();i++){var a=expected.segments().get(i);var b=actual.segments().get(i);if(i==0){if(!a.a().equals(b.a())||!a.b().equals(b.b())||Math.abs(a.to()-b.to())>1e-7||!a.span().shape().equals(b.span().shape()))throw new IllegalArgumentException("fleet_phase_start_changed");}else if(!a.equals(b))throw new IllegalArgumentException("fleet_phase_start_changed");}paths.put(phase,actual.save());trip.put("HeadPaths",paths);accounts.dirty();}
    public int headCursor(UUID order,String phase){var trip=trips.get(order);return trip==null?0:trip.getCompound("HeadCursor").getInt(phase);}
    public boolean headTravel(UUID order,String phase,int segment,RailGeometry.Span actual){var trip=trips.get(order);if(trip==null||trip.getBoolean("Closed")||!phase.equals(trip.getString("Phase"))||segment<headCursor(order,phase))return false;var data=trip.getCompound("Plan").getCompound("Phases").getCompound(phase);if(!data.contains("Path"))return false;var path=headPath(order,phase).orElseGet(()->RailRoutes.Path.load(data.getCompound("Path")));if(segment<0||segment>=path.segments().size()||path.segments().get(segment).span().overlap(actual)<actual.to()-actual.from()-.00001)return false;var consumed=trip.getCompound("HeadConsumed");String key=phase+"/"+segment;var previous=consumed.contains(key)?RailGeometry.Span.load(consumed.getCompound(key)):null;actual=unseen(actual,previous);if(actual==null)return false;if(previous!=null)actual=new RailGeometry.Span(actual.shape(),Math.min(previous.from(),actual.from()),Math.max(previous.to(),actual.to()));consumed.put(key,actual.save());trip.put("HeadConsumed",consumed);var cursor=trip.getCompound("HeadCursor");cursor.putInt(phase,segment);trip.put("HeadCursor",cursor);accounts.dirty();return true;}
    public boolean phaseComplete(UUID order,String phase){var trip=trips.get(order);if(trip==null)return false;var data=trip.getCompound("Plan").getCompound("Phases").getCompound(phase);if(!data.contains("Path"))return false;var path=headPath(order,phase).orElseGet(()->RailRoutes.Path.load(data.getCompound("Path")));var consumed=trip.getCompound("HeadConsumed");for(int i=0;i<path.segments().size();i++){var wanted=path.segments().get(i).span();if(wanted.to()-wanted.from()<1e-7)continue;String key=phase+"/"+i;if(!consumed.contains(key))return false;var actual=RailGeometry.Span.load(consumed.getCompound(key));if(!actual.shape().equals(wanted.shape())||actual.from()>wanted.from()+.00001||actual.to()<wanted.to()-.00001)return false;}return true;}
    public boolean finishTrip(UUID order){var t=trips.get(order);if(t==null||t.getBoolean("Closed"))return true;if(!flushPayables(t))return false;var payer=OwnerRef.load(t.getCompound("Payer"));long refund=t.getLong("Remaining");if(!accounts.canCredit(payer,refund))return false;if(refund>0)accounts.credit(payer,refund);t.putLong("Refunded",refund);t.putLong("Remaining",0);t.putBoolean("Closed",true);accounts.dirty();return true;}
    public boolean tripClosed(UUID order){var t=trips.get(order);return t==null||t.getBoolean("Closed");}
    /** Assessed debt is not revenue. Only cash that actually leaves the debtor reaches the creditor. */
    public void travel(UUID receipt,OwnerRef debtor,List<Charge> charges){
        if(receipts.contains(receipt))return;
        record Group(UUID road,OwnerRef creditor){}var accrued=new LinkedHashMap<Group,Long>();
        for(var c:charges){distance(c.road(),c.span().to()-c.span().from());if(debtor.equals(c.creditor()))continue;var group=new Group(c.road(),c.creditor());accrued.merge(group,units(c.span().to()-c.span().from(),c.rate()),Math::addExact);}
        for(var e:accrued.entrySet()){var group=e.getKey();String key=debtor+"/"+group.creditor()+"/"+group.road();long sum=Math.addExact(fractions.getOrDefault(key,0L),e.getValue()),amount=sum/1_000_000;fractions.put(key,sum%1_000_000);if(amount==0)continue;
            UUID debtId=component(receipt,group.toString());var debt=new Debt(debtId,debtor,group.creditor(),group.road(),amount,0);debts.put(debtId,debt);pay(debtId,Math.min(amount,accounts.balance(debtor)),component(receipt,"initial/"+group));}
        receipts.add(receipt);accounts.dirty();
    }
    /** Unowned trains accrue a technical obligation; no player UUID is invented and no CR are issued. */
    public void travelUnowned(UUID receipt,UUID train,String name,List<Charge> charges){if(receipts.contains(receipt))return;record Group(UUID road,OwnerRef creditor){}var groups=new LinkedHashMap<Group,Long>();for(var c:charges){distance(c.road(),c.span().to()-c.span().from());groups.merge(new Group(c.road(),c.creditor()),units(c.span().to()-c.span().from(),c.rate()),Math::addExact);}
        for(var e:groups.entrySet()){var group=e.getKey();String key="TRAIN/"+train+"/"+group.creditor()+"/"+group.road();var metadata=technicalFractions.computeIfAbsent(key,k->{var t=new CompoundTag();t.putUUID("Train",train);t.putUUID("Road",group.road());t.put("Creditor",group.creditor().save());t.putUUID("Epoch",UUID.randomUUID());return t;});long sum=Math.addExact(fractions.getOrDefault(key,0L),e.getValue());fractions.put(key,sum%1_000_000);long amount=sum/1_000_000;if(amount>0){UUID id=component(receipt,group.toString());technical.put(id,new TechnicalDebt(id,train,name,group.creditor(),group.road(),amount,null));}}
        receipts.add(receipt);accounts.dirty();
    }
    public void resolveTechnical(UUID train,OwnerRef responsible){boolean changed=false;for(var entry:new ArrayList<>(technical.entrySet())){var old=entry.getValue();if(!old.train().equals(train)||old.resolved()!=null)continue;
            if(debts.putIfAbsent(old.id(),new Debt(old.id(),responsible,old.creditor(),old.road(),old.assessed(),responsible.equals(old.creditor())?old.assessed():0))!=null)throw new IllegalArgumentException("rail_technical_identity_conflict");technical.put(old.id(),new TechnicalDebt(old.id(),old.train(),old.name(),old.creditor(),old.road(),old.assessed(),responsible));if(!responsible.equals(old.creditor()))pay(old.id(),Math.min(old.assessed(),accounts.balance(responsible)),component(old.id(),"resolved"));changed=true;}
        var iterator=technicalFractions.entrySet().iterator();while(iterator.hasNext()){var entry=iterator.next();var t=entry.getValue();if(!t.getUUID("Train").equals(train))continue;var creditor=OwnerRef.load(t.getCompound("Creditor"));UUID road=t.getUUID("Road");String key=responsible+"/"+creditor+"/"+road;long sum=Math.addExact(fractions.getOrDefault(key,0L),fractions.getOrDefault(entry.getKey(),0L));fractions.put(key,sum%1_000_000);fractions.remove(entry.getKey());long amount=sum/1_000_000;if(amount>0&&!responsible.equals(creditor)){UUID id=t.getUUID("Epoch");debts.put(id,new Debt(id,responsible,creditor,road,amount,0));pay(id,Math.min(amount,accounts.balance(responsible)),component(id,"resolved"));}iterator.remove();changed=true;}
        if(changed)accounts.dirty();
    }
    public long repay(UUID debt,long amount,UUID nonce){if(amount<=0)throw new IllegalArgumentException("rail_payment_invalid");return pay(debt,amount,nonce);}
    private long pay(UUID id,long requested,UUID nonce){
        if(receipts.contains(nonce))return 0;var old=debts.get(id);if(old==null)throw new IllegalArgumentException("rail_debt_missing");long paid=Math.min(requested,old.remaining());
        if(paid<=0||!accounts.canReceivePayments(Map.of(old.creditor(),paid),Map.of())||!accounts.debit(old.debtor(),paid))return 0;
        accounts.revenue(nonce,old.creditor(),paid);paid(old.road(),paid);debts.put(id,new Debt(id,old.debtor(),old.creditor(),old.road(),old.assessed(),Math.addExact(old.paid(),paid)));receipts.add(nonce);accounts.dirty();return paid;
    }
    public static UUID component(UUID id,String suffix){return UUID.nameUUIDFromBytes((id+"/"+suffix).getBytes(StandardCharsets.UTF_8));}
    public CompoundTag save(){var root=new CompoundTag();root.putInt("Version",1);var rs=new ListTag();for(var r:roads.values()){var t=new CompoundTag();t.putUUID("Id",r.id());t.put("Owner",r.owner().save());t.putString("Name",r.name());t.putLong("Rate",r.rate());t.putLong("Revision",r.revision());t.putBoolean("Active",r.active());var spans=new ListTag();r.spans().forEach(x->spans.add(x.save()));t.put("Spans",spans);rs.add(t);}root.put("Roads",rs);
        var ds=new ListTag();for(var d:debts.values()){var t=new CompoundTag();t.putUUID("Id",d.id());t.put("Debtor",d.debtor().save());t.put("Creditor",d.creditor().save());t.putUUID("Road",d.road());t.putLong("Assessed",d.assessed());t.putLong("Paid",d.paid());ds.add(t);}root.put("Debts",ds);
        var fs=new CompoundTag();fractions.forEach(fs::putLong);root.put("Fractions",fs);var ts=new ListTag();trips.forEach((id,data)->{var t=data.copy();t.putUUID("Id",id);ts.add(t);});root.put("Trips",ts);var ids=new ListTag();receipts.stream().sorted().forEach(id->ids.add(NbtUtils.createUUID(id)));root.put("Receipts",ids);var visits=new CompoundTag();passages.forEach((key,value)->visits.put(key,value.copy()));root.put("Passages",visits);root.putBoolean("LegacyCaptured",legacyCaptured);var legacy=new ListTag();legacyOrders.stream().sorted().forEach(id->legacy.add(NbtUtils.createUUID(id)));root.put("LegacyOrders",legacy);
        var tech=new ListTag();for(var d:technical.values()){var t=new CompoundTag();t.putUUID("Id",d.id());t.putUUID("Train",d.train());t.putString("Name",d.name());t.put("Creditor",d.creditor().save());t.putUUID("Road",d.road());t.putLong("Assessed",d.assessed());if(d.resolved()!=null)t.put("Resolved",d.resolved().save());tech.add(t);}root.put("TechnicalDebts",tech);var tf=new CompoundTag();technicalFractions.forEach((key,value)->tf.put(key,value.copy()));root.put("TechnicalFractions",tf);var stats=new ListTag();statistics.forEach((id,data)->{var t=data.copy();t.putUUID("Id",id);stats.add(t);});root.put("Statistics",stats);var streams=new ListTag();meterSequences.forEach((id,last)->{var t=new CompoundTag();t.putUUID("Id",id);t.putLong("Last",last);streams.add(t);});root.put("MeterStreams",streams);return root;}
    public void load(CompoundTag root){if(root.isEmpty())return;if(root.getInt("Version")!=1)throw new IllegalArgumentException("Unsupported road financial data");roads.clear();debts.clear();fractions.clear();trips.clear();receipts.clear();
        for(var raw:root.getList("Roads",10)){var t=(CompoundTag)raw;var spans=new ArrayList<RailGeometry.Span>();for(var value:t.getList("Spans",10))spans.add(RailGeometry.Span.load((CompoundTag)value));var r=new Road(t.getUUID("Id"),OwnerRef.load(t.getCompound("Owner")),t.getString("Name"),t.getLong("Rate"),t.getLong("Revision"),t.getBoolean("Active"),spans);if(roads.putIfAbsent(r.id(),r)!=null)throw new IllegalArgumentException("Duplicate road");}
        for(var raw:root.getList("Debts",10)){var t=(CompoundTag)raw;var d=new Debt(t.getUUID("Id"),OwnerRef.load(t.getCompound("Debtor")),OwnerRef.load(t.getCompound("Creditor")),t.getUUID("Road"),t.getLong("Assessed"),t.getLong("Paid"));if(d.paid()<0||d.assessed()<d.paid()||debts.putIfAbsent(d.id(),d)!=null)throw new IllegalArgumentException("Invalid debt");}
        var fs=root.getCompound("Fractions");for(String key:fs.getAllKeys()){long value=fs.getLong(key);if(value<0||value>=1_000_000)throw new IllegalArgumentException("Invalid fractional toll");fractions.put(key,value);}
        for(var raw:root.getList("Trips",10)){var t=((CompoundTag)raw).copy();OwnerRef.load(t.getCompound("Payer"));if(t.getLong("Reserved")<0||t.getLong("Remaining")<0||t.getLong("Remaining")>t.getLong("Reserved")||t.getLong("Refunded")<0||t.getLong("Refunded")>t.getLong("Reserved")||trips.putIfAbsent(t.getUUID("Id"),t)!=null)throw new IllegalArgumentException("Invalid trip reserve");long pending=0;var ids=new HashSet<UUID>();for(var value:t.getList("Payables",10)){var p=(CompoundTag)value;OwnerRef.load(p.getCompound("Creditor"));if(p.getLong("Amount")<=0||!p.hasUUID("Road")||!ids.add(p.getUUID("Id")))throw new IllegalArgumentException("Invalid funded road payable");pending=Math.addExact(pending,p.getLong("Amount"));}if(pending>t.getLong("Reserved")-t.getLong("Remaining")||t.getBoolean("Closed")&&(t.getLong("Remaining")!=0||pending!=0))throw new IllegalArgumentException("Unbalanced road reserve");var consumed=t.getCompound("Consumed");for(String key:consumed.getAllKeys())RailGeometry.Span.load(consumed.getCompound(key));}
        for(var raw:root.getList("Receipts",11))if(!receipts.add(NbtUtils.loadUUID(raw)))throw new IllegalArgumentException("Duplicate toll receipt");passages.clear();var visits=root.getCompound("Passages");for(String key:visits.getAllKeys())passages.put(key,visits.getCompound(key).copy());legacyCaptured=root.getBoolean("LegacyCaptured");legacyOrders.clear();for(var raw:root.getList("LegacyOrders",11))legacyOrders.add(NbtUtils.loadUUID(raw));
        technical.clear();for(var raw:root.getList("TechnicalDebts",10)){var t=(CompoundTag)raw;var d=new TechnicalDebt(t.getUUID("Id"),t.getUUID("Train"),t.getString("Name"),OwnerRef.load(t.getCompound("Creditor")),t.getUUID("Road"),t.getLong("Assessed"),t.contains("Resolved")?OwnerRef.load(t.getCompound("Resolved")):null);if(d.assessed()<0||technical.putIfAbsent(d.id(),d)!=null)throw new IllegalArgumentException("Invalid technical debt");}technicalFractions.clear();var tf=root.getCompound("TechnicalFractions");for(String key:tf.getAllKeys())technicalFractions.put(key,tf.getCompound(key).copy());
        statistics.clear();for(var raw:root.getList("Statistics",10)){var t=((CompoundTag)raw).copy();if(!Double.isFinite(t.getDouble("Distance"))||t.getDouble("Distance")<0||t.getLong("Paid")<0||statistics.putIfAbsent(t.getUUID("Id"),t)!=null)throw new IllegalArgumentException("Invalid road statistics");}
        meterSequences.clear();for(var raw:root.getList("MeterStreams",10)){var t=(CompoundTag)raw;if(t.getLong("Last")<0||meterSequences.putIfAbsent(t.getUUID("Id"),t.getLong("Last"))!=null)throw new IllegalArgumentException("Invalid meter sequence");}
    }
}
